n0:createOraclePackageBody.n0:source:
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "%USER_NAME%"."DEL" as
    PROCEDURE NOTE(NID IN NUMBER)
    AS
    BEGIN
        INSERT INTO deleted_notes
        SELECT *
        FROM notes
        WHERE n_id = nid;

        DELETE FROM notes
        WHERE n_id = nid;
    END;

    PROCEDURE OBJECTIVE(OID IN NUMBER)
    AS
    BEGIN
        INSERT INTO deleted_objectives
        SELECT *
        FROM objectives
        WHERE o_id = oid;

        DELETE FROM objectives
        WHERE o_id = oid;
    END;

    PROCEDURE SESSION(SID IN NUMBER)
    AS
    BEGIN
        INSERT INTO deleted_notes
        SELECT *
        FROM notes
        WHERE s_id = sid;

        DELETE FROM notes
        WHERE s_id = sid;

        INSERT INTO deleted_sessions
        SELECT *
        FROM sessions
        WHERE s_id = sid;

        DELETE FROM sessions
        WHERE s_id = sid;
    END;
end;
/
